from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal("0")
_EIGHT = Decimal("8")
_TEN = Decimal("10")


def _money(value: Any) -> Decimal:
    """Apply legacy NVL-to-zero and monetary half-up rounding semantics."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        number = value
    else:
        number = Decimal(str(value))
    return number.quantize(_CENT, rounding=ROUND_HALF_UP)


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    """Run the legacy nightly credit-hold sweep without mutating inputs."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    account_indices = sorted(
        range(len(new_accounts)),
        key=lambda index: new_accounts[index].get("ACCT_ID", ""),
    )
    ordered_orders = sorted(
        orders,
        key=lambda order: order.get("ORD_ID", ""),
    )

    precision = max(50, len(str(len(orders))) + 32)
    with localcontext() as context:
        context.prec = precision

        for index in account_indices:
            account = new_accounts[index]

            if account.get("DEL_FLG", "") == "Y":
                continue
            if account.get("ACCT_TYP", "") != "C":
                continue

            account_id = account.get("ACCT_ID", "")
            exposure = _ZERO

            for order in ordered_orders:
                if order.get("DEL_FLG", "") == "Y":
                    continue
                if order.get("ACCT_ID", "") != account_id:
                    continue
                if order.get("STAT_CD", "") == "I":
                    exposure += _money(order.get("TOT_AMT", ""))

            credit_limit = _money(account.get("CRED_LIMIT", ""))

            if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
                account["CRED_HOLD"] = "Y"
                audits.append(("CRED_HOLD_ON", account_id))

            release_threshold = credit_limit * _EIGHT / _TEN
            if (
                exposure <= release_threshold
                and account.get("CRED_HOLD", "") == "Y"
            ):
                account["CRED_HOLD"] = "N"
                audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
